-- The Ruilingen database schema (SQLite), generated from app/models.py.
-- GENERATED by `python -m scripts.dump_schema`; don't edit by hand. Changes go through
-- app/models.py and a migration (docs/architecture.md). Dates are UTC. The live file also has
-- an `alembic_version` table (which migration it is at), left out here. Meaning of each
-- column: docs/database.md.

CREATE TABLE app_settings (
	"key" VARCHAR(40) NOT NULL, 
	value TEXT NOT NULL, 
	PRIMARY KEY ("key")
);

CREATE TABLE users (
	id INTEGER NOT NULL, 
	email VARCHAR(254), 
	name VARCHAR(80) NOT NULL, 
	is_admin BOOLEAN NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	email_notifications BOOLEAN NOT NULL, 
	session_epoch INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (email)
);

CREATE TABLE invite_links (
	id INTEGER NOT NULL, 
	code VARCHAR(40) NOT NULL, 
	label VARCHAR(60) NOT NULL, 
	role VARCHAR(10) NOT NULL, 
	is_main BOOLEAN NOT NULL, 
	max_uses INTEGER, 
	uses INTEGER NOT NULL, 
	expires_at DATETIME, 
	revoked_at DATETIME, 
	created_by_id INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE listings (
	id INTEGER NOT NULL, 
	kind VARCHAR(10) NOT NULL, 
	user_id INTEGER NOT NULL, 
	date DATE NOT NULL, 
	start VARCHAR(5), 
	"end" VARCHAR(5), 
	daypart VARCHAR(10), 
	hall VARCHAR(60), 
	workplace VARCHAR(60), 
	shift_type VARCHAR(8), 
	wanted_types VARCHAR(80), 
	note TEXT NOT NULL, 
	mode VARCHAR(5) DEFAULT 'give' NOT NULL, 
	want_from DATE, 
	want_to DATE, 
	want_types VARCHAR(80), 
	status VARCHAR(10) NOT NULL, 
	created_at DATETIME NOT NULL, 
	closed_at DATETIME, 
	mail_sent_at DATETIME, 
	mail_sent_by_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(mail_sent_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_listings_date ON listings (date);

CREATE INDEX ix_listings_user_id ON listings (user_id);

CREATE TABLE login_tokens (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	email VARCHAR(254), 
	created_at DATETIME NOT NULL, 
	expires_at DATETIME NOT NULL, 
	used_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	UNIQUE (token_hash)
);

CREATE INDEX ix_login_tokens_user_id ON login_tokens (user_id);

CREATE TABLE notifications (
	id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	text TEXT NOT NULL, 
	link VARCHAR(200) NOT NULL, 
	created_at DATETIME NOT NULL, 
	read_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_notifications_user_id ON notifications (user_id);

CREATE TABLE reactions (
	id INTEGER NOT NULL, 
	listing_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	offer_start VARCHAR(5), 
	offer_end VARCHAR(5), 
	offer_daypart VARCHAR(10), 
	offer_date DATE, 
	offer_listing_id INTEGER, 
	offer_hall VARCHAR(60), 
	offer_workplace VARCHAR(60), 
	offer_type VARCHAR(8), 
	created_at DATETIME NOT NULL, 
	decided_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(listing_id) REFERENCES listings (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT fk_reactions_offer_listing FOREIGN KEY(offer_listing_id) REFERENCES listings (id) ON DELETE SET NULL
);

CREATE INDEX ix_reactions_listing_id ON reactions (listing_id);

CREATE INDEX ix_reactions_user_id ON reactions (user_id);

CREATE UNIQUE INDEX uq_reaction_pending ON reactions (listing_id, user_id) WHERE status = 'pending';
